@test
def test_anova_rm():
    D = np.empty((8, 6, 5))
    for k in range(6):
        D[:, k, :] = data(8, 5, float(k), 0.1 * k)
    f, pv = S.f_mway_rm(D, [2, 3])
    assert close(f, [0.6182586094471427, 0.6335516173054311, 0.8063305600445984, 0.05117861713567247, 0.33981514078576947, 31.68196295134908, 37.60210738111119, 46.90110282870385, 26.160964439633414, 33.19259155737792, 0.494524245165704, 0.6558263008699046, 0.19172866479030595, 0.04590324196861165, 0.01822116297475304], 1e-8)
    assert close(pv, [0.4574824477190596, 0.4521988538962726, 0.3990385924076311, 0.8274887797239494, 0.5782234588116814, 6.355163784709714e-06, 2.3453012092721143e-06, 6.230210534568481e-07, 1.8676530860472265e-05, 4.860312703773837e-06, 0.6201229405913522, 0.5342466164645217, 0.8276623974749332, 0.9552775150475925, 0.9819670855171192], 1e-7)
    f, pv = S.f_mway_rm(D, [2, 3], effects="A:B", correction=True)
    assert close(f, [0.494524245165704, 0.6558263008699046, 0.19172866479030595, 0.04590324196861165, 0.01822116297475304], 1e-8)
    assert close(pv, [0.5452856580744504, 0.47769406197816183, 0.7247997397614656, 0.8726493037951857, 0.9208330890434185], 1e-7)
    assert close(np.array(S.f_threshold_mway_rm(8, [2, 3])), [5.591447851220735, 3.738891832440735, 3.738891832440735], 1e-8)
    assert close(np.array(S.f_threshold_mway_rm(8, [2, 3], effects="B", pvalue=0.01)), [6.514884102182749], 1e-8)


