@test
def test_linear_regression():
    info = mne.create_info(["a", "b", "c"], 100.0, "eeg")
    D = np.empty((15, 3, 20))
    for e in range(15):
        D[e] = data(3, 20, 0.1 * e, 0.0) * 1e-6
    ep = mne.EpochsArray(D, info, tmin=-0.05)
    dm = np.empty((15, 3))
    for i in range(15):
        dm[i, 0] = 1.0
        dm[i, 1] = float(i % 3)
        dm[i, 2] = np.sin(float(i))
    lm = S.linear_regression(ep, dm, names=["icpt", "cond", "s"])
